-- Users of every role, with status, mobile number and role checks.
-- Tables: User
-- Generated by server/scripts/export-sql.mjs from the migrated database. Run the files in numeric order on an empty database.

BEGIN;

CREATE TABLE public."User" (
    id text NOT NULL,
    name text NOT NULL,
    email text NOT NULL,
    password text NOT NULL,
    role public."Role" NOT NULL,
    "collegeId" text,
    i_ts timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    u_ts timestamp(3) without time zone,
    crte_usr_id text,
    updte_usr_id text,
    a_in smallint DEFAULT 1 NOT NULL,
    d_ts timestamp(3) without time zone,
    mobile_no text,
    role_id integer DEFAULT 4 NOT NULL,
    status public."UserStatus" DEFAULT 'ACTIVE'::public."UserStatus" NOT NULL,
    CONSTRAINT "User_a_in_check" CHECK ((a_in = ANY (ARRAY[0, 1])))
);

ALTER TABLE ONLY public."User"
    ADD CONSTRAINT "User_pkey" PRIMARY KEY (id);

CREATE UNIQUE INDEX "User_collegeId_email_key" ON public."User" USING btree ("collegeId", email);

CREATE UNIQUE INDEX "User_collegeId_mobile_no_key" ON public."User" USING btree ("collegeId", mobile_no);

CREATE UNIQUE INDEX "User_platform_email_key" ON public."User" USING btree (email) WHERE ("collegeId" IS NULL);

CREATE TRIGGER "User_audit_timestamps" BEFORE UPDATE ON public."User" FOR EACH ROW EXECUTE FUNCTION public.campus_set_audit_timestamps();

CREATE TRIGGER "User_sync_role" BEFORE INSERT OR UPDATE OF role, role_id ON public."User" FOR EACH ROW EXECUTE FUNCTION public.campus_sync_user_role();

-- Foreign keys
ALTER TABLE ONLY public."User"
    ADD CONSTRAINT "User_collegeId_fkey" FOREIGN KEY ("collegeId") REFERENCES public."College"(id) ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE ONLY public."User"
    ADD CONSTRAINT "User_role_id_role_fkey" FOREIGN KEY (role_id, role) REFERENCES public.role_t(role_id, role_code) ON UPDATE CASCADE ON DELETE RESTRICT;

COMMIT;
